<?= $this->extend('layouts/main') ?><?= $this->section('content') ?>
<section class="wrap product-detail"><div class="detail-image"><?php if ($image = product_image_url($product['image'])): ?><img src="<?= esc($image) ?>" alt="<?= esc($product['name']) ?>" width="900" height="900" fetchpriority="high"><?php else: ?><div class="image-fallback">No product image available</div><?php endif ?></div><div><a class="text-link" href="<?= site_url('catalog') ?>">Back to products</a><h1><?= esc($product['name']) ?></h1><p class="detail-price"><?= format_rupiah((string) $product['price']) ?></p><p><?= esc($product['description']) ?></p><p><?= (int) $product['stock'] > 0 ? 'In stock: ' . (int) $product['stock'] : 'Out of stock' ?></p><?php if ((int) $product['stock'] > 0): ?><?php if (session('logged_in') && session('role') === 'customer'): ?><form class="account-form" method="post" action="<?= site_url('cart/items') ?>"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= esc($product['id']) ?>"><label for="quantity">Quantity</label><input id="quantity" type="number" name="quantity" value="1" min="1" max="<?= (int) $product['stock'] ?>" required><button class="button button-dark" type="submit">Add to cart</button></form><?php elseif (! session('logged_in')): ?><a class="button button-dark" href="<?= site_url('login') ?>?return_to=<?= rawurlencode('/product/' . $product['slug']) ?>">Sign in to add to cart</a><?php endif ?><?php endif ?></div></section>
<?= $this->endSection() ?>
